using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SelflessIgniteCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/SelflessIgniteCustomDescription", order = 0)]
public class SelflessIgniteCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		string text = Smart.Format(GetRawLocalizedDescription(battleAction), 1);
		AfflictionDefaultEffectAction afflictionDefaultEffectAction = (battleAction as SelflessIgniteAction).AfflictionDefaultEffectAction;
		return text + "\n" + afflictionDefaultEffectAction.GetActionDescription(GetFinalAmountWithoutEquation(amountModified));
	}
}
